class SubprocessTests(CliCase):
    def run_module(self, *argv, stdin=None):
        env = dict(os.environ, PYTHONPATH=ROOT)
        return subprocess.run(
            [sys.executable, "-m", "pennywise", *argv],
            input=stdin, capture_output=True, text=True, env=env, cwd=self.dir,
        )

    def test_module_balance(self):
        r = self.run_module("balance", self.path)
        self.assertEqual((r.returncode, r.stdout, r.stderr), (0, "1457.50\n", ""))

    def test_module_stdin(self):
        r = self.run_module("balance", "-", stdin=LEDGER)
        self.assertEqual((r.returncode, r.stdout), (0, "1457.50\n"))

    def test_module_ledger_error(self):
        bad = self.write("bad.txt", "oops\n")
        r = self.run_module("balance", bad)
        self.assertEqual((r.returncode, r.stdout), (1, ""))
        self.assertIn("line 1", r.stderr)

    def test_module_usage_error(self):
        r = self.run_module()
        self.assertEqual((r.returncode, r.stdout), (2, ""))


class ClosedPipeTests(CliCase):
    """The reader closing the pipe early must end quietly, status 0."""

    def big_ledger(self, groups=False):
        n = 100000
        if groups:
            lines = ["2024-03-%02d cat%d -1.00 n" % (i % 28 + 1, i) for i in range(n)]
        else:
            lines = ["2024-03-%02d food -1.00 n" % (i % 28 + 1) for i in range(n)]
        return self.write("big.txt", "\n".join(lines) + "\n")

    def read_one_line_then_close(self, argv, stdin_path=None):
        env = dict(os.environ, PYTHONPATH=ROOT)
        stdin = open(stdin_path, "rb") if stdin_path else None
        try:
            proc = subprocess.Popen(
                [sys.executable, "-m", "pennywise", *argv],
                stdin=stdin, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env,
            )
            first = proc.stdout.readline()
            proc.stdout.close()
            err = proc.stderr.read()
            code = proc.wait(timeout=60)
            proc.stderr.close()
        finally:
            if stdin:
                stdin.close()
        return first, err, code

    def check(self, argv, stdin_path=None):
        first, err, code = self.read_one_line_then_close(argv, stdin_path)
        self.assertTrue(first.endswith(b"\n"))
        self.assertNotIn(b"Traceback", err)
        self.assertEqual((err, code), (b"", 0))

    def test_list_closed_pipe(self):
        self.check(["list", self.big_ledger()])

    def test_export_closed_pipe(self):
        self.check(["export", self.big_ledger()])

    def test_list_stdin_closed_pipe(self):
        self.check(["list", "-"], stdin_path=self.big_ledger())

    def test_summary_many_groups_closed_pipe(self):
        self.check(["summary", self.big_ledger(groups=True)])

